transfer.sketch:
value Money: amount, tags: { unit: Currency, asOf: Date }
value Conv:  from: Currency, to: Currency, lossless(p) → bool, cost, params(tags) → Rate   -- rate on tags.asOf
value OpRule: sameUnit: bool, result: follows | declared(Currency)

build(op, recv, args) → Node | Refusal      -- recv = report column, home currency
  inputs = [recv] ++ amountArgs(args)
  if rule.sameUnit:
    for x in inputs[1:]:
      if x.unit ≠ recv.unit:
        return refuse(E_UNIT, from: x.unit, to: recv.unit,
                      fix: "rows.groupBy(unit), then convert each subtotal on its own asOf")
  conv = [convertTo(x, recv.unit) for x in inputs]      -- keyed by x.tags.asOf, not today
  return node(op, conv, bindArgs(args))                 -- percent args bind to fraction of total

convertTo(x, c, acceptLoss: false):
  path = catalogue.cheapestPath(x.unit, c)              -- params(x.tags) = rate on x.tags.asOf
  if not all(k.lossless(p) for k in path) and not acceptLoss:
    return refuse(E_LOSSY, fix: "total.as(\"JPY\") rounds on purpose")

